package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;
import net.minecraft.client.Minecraft;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.InteractionHand;import net.minecraft.network.protocol.game.*;import net.minecraft.world.phys.*;import net.minecraft.world.level.ClipContext;import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;
import java.util.*;import net.minecraft.resources.ResourceLocation;
/** Owns asynchronous menu opening and explicit operations, with restoration cleanup. */
public final class ContainerSessions implements Jobs.Step,Jobs.Cleanup {
 private final String action;private final JsonObject args;private final boolean packet;
 private boolean started,opened,finished,sent;private int originalId,ownedId=-1,step,delay;private long next;private Object originalLevel;private JsonArray steps;private JsonObject baseline;
 public ContainerSessions(String name,JsonObject a,boolean packet){action=name;args=a.deepCopy();this.packet=packet;}
 public JsonObject tick()throws Exception {Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return Jsons.error("not_in_world");AbstractContainerMenu menu=mc.player.containerMenu;
  if(!started){started=true;originalLevel=mc.level;originalId=menu.containerId;if(!menu.getCarried().isEmpty()&&(!action.equals("container.click")||args.has("target")))return Jsons.error("cursor_not_empty");
   JsonObject target=Jsons.object(args,"target");if(menu!=mc.player.inventoryMenu){if(target.size()!=0){BlockPos pos=position(target);if(!menu.stillValid(mc.player)||!matchesTarget(menu,pos))return Jsons.error("another_container_is_open_close_or_explicitly_reuse");}ownedId=menu.containerId;}
   else if(target.size()!=0){Actions.interactBlock(target,packet);opened=true;return pending("opening");}else ownedId=0;
  }
  if(mc.level!=originalLevel)return Jsons.error("world_changed");
  if(ownedId<0){if(menu==mc.player.inventoryMenu){if(++delay>100)return Jsons.error("container_open_timeout");return pending("opening");}ownedId=menu.containerId;}
  if(menu.containerId!=ownedId)return Jsons.error("menu_changed_by_player");
  if(steps==null){baseline=snapshot(menu);steps=plan(menu);if(steps==null)return Jsons.error("invalid_container_operation");}
  if(System.nanoTime()<next)return pending("synchronizing");
  if(step<steps.size()){JsonObject s=steps.get(step).getAsJsonObject();JsonObject result=perform(menu,s);if(result.has("pending"))return result;if(result.has("error"))return result;step++;next=System.nanoTime()+100000000L;return pending("operating");}
  JsonObject after=snapshot(menu);JsonObject beforeBusiness=baseline.deepCopy(),afterBusiness=after.deepCopy();beforeBusiness.remove("state_id");afterBusiness.remove("state_id");boolean changed=!beforeBusiness.equals(afterBusiness);boolean require=Jsons.bool(args,"require_change",true);if(require&&!changed&&++delay<20)return pending("verifying");
  if(require&&!changed)return Jsons.obj("error","no_observed_change","before",baseline,"after",after,"steps",step);
  if(!menu.getCarried().isEmpty()&&(opened||!action.equals("container.click")))return Jsons.obj("error","cursor_not_empty_after_operation","after",after);
  finished=true;return Jsons.obj("observed_success",changed,"steps",step,"before",baseline,"after",after,"initial_open",originalId!=0,"restoration",opened?"close_owned_menu":"keep_original_menu");
 }
 private static boolean matchesTarget(AbstractContainerMenu menu,BlockPos p){return p.equals(Actions.lastOpenedPosition);}
 private JsonArray plan(AbstractContainerMenu menu){JsonArray list=new JsonArray();if(args.has("steps")){list=Jsons.array(args,"steps").deepCopy();if(list.size()>64)throw new IllegalArgumentException("too_many_steps");return list;}
  switch(action){
   case "container.click" -> list.add(args.deepCopy());
   case "container.move" -> {int from=Jsons.integer(args,"from_slot",-1),to=Jsons.integer(args,"to_slot",-1);int count=Jsons.integer(args,"count",-1);Slot source=slot(menu,from);if(source.getItem().isEmpty())throw new IllegalArgumentException("source_empty");if(!slot(menu,to).getItem().isEmpty()&&!ItemStack.isSameItemSameTags(source.getItem(),slot(menu,to).getItem()))throw new IllegalArgumentException("destination_item_conflict");if(count>source.getItem().getCount())throw new IllegalArgumentException("insufficient_items");list.add(Jsons.obj("op","click","slot",from,"button",0,"click","pickup"));if(count>0&&count<source.getItem().getCount()){if(count>32)throw new IllegalArgumentException("partial_transfer_limit_32");for(int i=0;i<count;i++)list.add(Jsons.obj("op","click","slot",to,"button",1,"click","pickup"));list.add(Jsons.obj("op","click","slot",from,"button",0,"click","pickup"));}else list.add(Jsons.obj("op","click","slot",to,"button",0,"click","pickup"));}
   case "container.craft" -> {list.add(Jsons.obj("op","recipe","recipe_id",Jsons.str(args,"recipe_id",""),"all",Jsons.bool(args,"all",false)));list.add(Jsons.obj("op","wait_result","slot",0,"timeout_ticks",80));if(Jsons.bool(args,"take_result",true))list.add(Jsons.obj("op","click","slot",0,"click","quick_move","button",0));}
   case "container.button" -> list.add(Jsons.obj("op","button","button",Jsons.integer(args,"button",0)));
   case "container.rename" -> list.add(Jsons.obj("op","rename","text",Jsons.str(args,"text","")));
   default -> {if(action.equals("inventory.equip")||action.equals("inventory.unequip")){list.add(Jsons.obj("op","click","slot",Jsons.integer(args,"slot",-1),"click","quick_move","button",0));}else return null;}
  }return list;
 }
 private JsonObject perform(AbstractContainerMenu menu,JsonObject s)throws Exception{Minecraft mc=Minecraft.getInstance();String op=Jsons.str(s,"op","click");switch(op){
  case "wait_result" -> {Slot out=slot(menu,Jsons.integer(s,"slot",0));if(out.getItem().isEmpty()){if(++delay>Jsons.integer(s,"timeout_ticks",100))return Jsons.error("result_timeout");return pending("waiting_result");}delay=0;return new JsonObject();}
  case "wait" -> {if(++delay<Jsons.integer(s,"ticks",2))return pending("waiting");delay=0;return new JsonObject();}
  case "recipe" -> {if(!(menu instanceof RecipeBookMenu<?> book))return Jsons.error("menu_has_no_recipe_book");ResourceLocation id=ResourceLocation.tryParse(Jsons.str(s,"recipe_id",""));var recipe=id==null?Optional.<net.minecraft.world.item.crafting.Recipe<?>>empty():mc.level.getRecipeManager().byKey(id);if(recipe.isEmpty())return Jsons.error("unknown_recipe");if(!recipe.get().canCraftInDimensions(book.getGridWidth(),book.getGridHeight()))return Jsons.error("recipe_does_not_fit");if(packet)PacketService.sendPacket(new ServerboundPlaceRecipePacket(menu.containerId,recipe.get(),Jsons.bool(s,"all",false)));else mc.gameMode.handlePlaceRecipe(menu.containerId,recipe.get(),Jsons.bool(s,"all",false));return new JsonObject();}
  case "button" -> {int button=Jsons.integer(s,"button",0);if(packet)PacketService.sendPacket(new ServerboundContainerButtonClickPacket(menu.containerId,button));else mc.gameMode.handleInventoryButtonClick(menu.containerId,button);return new JsonObject();}
  case "rename" -> {if(!(menu instanceof AnvilMenu))return Jsons.error("anvil_menu_required");String text=Jsons.str(s,"text","");if(text.length()>50)return Jsons.error("name_too_long");PacketService.sendPacket(new ServerboundRenameItemPacket(text));return new JsonObject();}
  case "click" -> {int index=Jsons.integer(s,"slot",-1);Slot slot=slot(menu,index);if(s.has("expected_item")&&!BuiltInRegistries.ITEM.getKey(slot.getItem().getItem()).toString().equals(Jsons.str(s,"expected_item","")))return Jsons.error("slot_precondition_changed");if(s.has("expected_carried")&&!BuiltInRegistries.ITEM.getKey(menu.getCarried().getItem()).toString().equals(Jsons.str(s,"expected_carried","")))return Jsons.error("cursor_precondition_changed");ClickType type=switch(Jsons.str(s,"click","pickup")){case "pickup"->ClickType.PICKUP;case "quick_move"->ClickType.QUICK_MOVE;case "swap"->ClickType.SWAP;case "throw"->ClickType.THROW;case "pickup_all"->ClickType.PICKUP_ALL;default->throw new IllegalArgumentException("unsupported_click");};int button=Jsons.integer(s,"button",0);if(button<0||button>8)throw new IllegalArgumentException("invalid_button");click(menu,index,button,type,packet);return new JsonObject();}
  default -> {return Jsons.error("unknown_container_step");}}
 }
 public static void click(AbstractContainerMenu menu,int index,int button,ClickType type,boolean packet){Minecraft mc=Minecraft.getInstance();if(!packet){mc.gameMode.handleInventoryMouseClick(menu.containerId,index,button,type,mc.player);return;}
  List<ItemStack> before=new ArrayList<>();for(Slot s:menu.slots)before.add(s.getItem().copy());menu.clicked(index,button,type,mc.player);Int2ObjectOpenHashMap<ItemStack> changes=new Int2ObjectOpenHashMap<>();for(int i=0;i<Math.min(menu.slots.size(),128);i++)if(!ItemStack.matches(before.get(i),menu.slots.get(i).getItem()))changes.put(i,menu.slots.get(i).getItem().copy());PacketService.sendPacket(new ServerboundContainerClickPacket(menu.containerId,menu.getStateId(),index,button,type,menu.getCarried().copy(),changes));}
 private static Slot slot(AbstractContainerMenu m,int index){if(index<0||!m.isValidSlotIndex(index))throw new IllegalArgumentException("slot_out_of_range");return m.getSlot(index);}
 private static BlockPos position(JsonObject p){return new BlockPos(Jsons.integer(p,"x",0),Jsons.integer(p,"y",0),Jsons.integer(p,"z",0));}
 public static JsonObject snapshot(AbstractContainerMenu m){JsonArray slots=new JsonArray();for(int i=0;i<Math.min(512,m.slots.size());i++){Slot s=m.slots.get(i);slots.add(Jsons.obj("slot",i,"container_slot",s.getContainerSlot(),"item_id",BuiltInRegistries.ITEM.getKey(s.getItem().getItem()).toString(),"count",s.getItem().getCount(),"player_inventory",s.container==Minecraft.getInstance().player.getInventory()));}JsonObject out=Jsons.obj("menu_id",m.containerId,"class",m.getClass().getName(),"state_id",m.getStateId(),"carried",BuiltInRegistries.ITEM.getKey(m.getCarried().getItem()).toString(),"carried_count",m.getCarried().getCount(),"slots",slots);if(m instanceof AbstractFurnaceMenu f)out.add("workstation",Jsons.obj("kind","furnace","input_slot",0,"fuel_slot",1,"result_slot",2,"lit",f.isLit(),"cook_progress",f.getBurnProgress(),"fuel_progress",f.getLitProgress()));else if(m instanceof BrewingStandMenu b)out.add("workstation",Jsons.obj("kind","brewing","bottle_slots",List.of(0,1,2),"ingredient_slot",3,"fuel_slot",4,"fuel",b.getFuel(),"brew_ticks",b.getBrewingTicks()));else if(m instanceof AnvilMenu a)out.add("workstation",Jsons.obj("kind","anvil","input_slots",List.of(0,1),"result_slot",2,"experience_cost",a.getCost()));else if(m instanceof StonecutterMenu s)out.add("workstation",Jsons.obj("kind","stonecutter","input_slot",0,"result_slot",1,"selected",s.getSelectedRecipeIndex(),"recipes",s.getRecipes().stream().limit(128).map(r->r.getId().toString()).toList()));else if(m instanceof RecipeBookMenu<?> b)out.add("workstation",Jsons.obj("kind","recipe_book","width",b.getGridWidth(),"height",b.getGridHeight(),"result_slot",b.getResultSlotIndex()));return out;}
 private JsonObject pending(String phase){return Jsons.obj("pending",true,"phase",phase,"step",step,"owned_menu",ownedId);}
 public void cleanup(){Minecraft mc=Minecraft.getInstance();if(opened&&mc.player!=null&&mc.level==originalLevel&&mc.player.containerMenu.containerId==ownedId&&mc.player.containerMenu.getCarried().isEmpty()){if(packet){PacketService.sendPacket(new ServerboundContainerClosePacket(ownedId));mc.player.containerMenu=mc.player.inventoryMenu;mc.setScreen(null);}else mc.player.closeContainer();}}
}
